                color: activeTab === tab.id ? 'var(--button-bg)' : 'var(--text-color)',
                cursor: 'pointer',
                fontSize: '0.9rem',
                fontWeight: activeTab === tab.id ? 600 : 400,
                transition: 'all 0.2s',
