            <button
              onClick={handleSyncNexup}
              disabled={nexupLoading || syncProgress}
              className="button"
              style={{ backgroundColor: '#ffc230', color: '#1a1a1a' }}
            >
              {syncProgress ? <><Loader2 size={16} className="spin" />Syncing...</> : 'Download Trailers'}
            </button>
